                adj[u].append(v)
                adj[v].append(u)
        except (IndexError, ValueError):
            break

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(count)

    sort descending to try to use larger components first (greedy heuristic for DP state)
    component_sizes.sort(reverse=True)

    # Generate lucky numbers up to n
    lucky_numbers = []
    def generate(current):
        if 1 <= current <= n:
            lucky_numbers.append(current)
        if current * 10 <= n:
            for digit in [4, 7]:
                generate(current * 10 + digit)

    for digit in [4, 7]:
        generate(digit)

    lucky_set = set(lucky_numbers)

    # DP: dp[s] = minimum number of components needed to get sum s
    dp = {0: 0}

    for size in component_sizes:
        new_dp = dp.copy()
        for s, count in dp.items():
            new_sum = s + size
            if new_sum <= n and (new_sum not in new_dp or new_dp[new_sum] > count + 1):
                new_dp[new_sum] = count + 1
        dp = new_dp

    # Find minimum roads needed
    min_roads = float('inf')

