def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    MOD = 1000000007

    # Find positions that need filling and which values are missing
    pos_ones = []  # positions (1-indexed) with -1
    present = set()

    for i, val in enumerate(arr):
        if val == -1:
            pos_ones.append(i + 1)
        else:
            present.add(val)

    # Find which values are missing from the permutation
    missing = set(range(1, n + 1)) - present

    # Count overlap: positions where i is in pos_ones AND value i is missing
    overlap = 0
    for i in pos_ones:
        if i in missing:
            overlap += 1

    size = len(pos_ones)  # number of -1 positions

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Precompute modular inverse of factorials for combinations
    inv_fact = [1] * (n + 1)
    inv = pow(fact[n], MOD - 2, MOD)
    for i in range(n, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD

    # nCr using precomputed factorials
    def nCr_mod(n, r):
        if r < 0 or r > n:
            return 0
        return (fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD)

    # Inclusion-exclusion to count valid derangements
    result = 0
    for j in range(overlap + 1):
        # C(overlap, j) * (size - j)!
        ways = (nCr_mod(overlap, j) * fact[size - j]) % MOD

        if j % 2 == 1:
            result = (result - ways + MOD) % MOD
        else:
            result = (result + ways) % MOD

    return str(result)

