        diagonal_xor = {}
        for r in range(n):
            if idx >= len(lines):
                break
            row = list(map(int, lines[idx].strip().split()))
            idx += 1
            for c, val in enumerate(row):
                diag_key = r - c
                if diag_key not in diagonal_xor:
                    diagonal_xor[diag_key] = 0
                diagonal_xor[diag_key] ^= val

        # Compute overall XOR of all diagonals
        overall_xor = 0
        for val in diagonal_xor.values():
            overall_xor ^= val

        # If overall XOR is non-zero, Ashish wins; otherwise, Jeel wins
        if overall_xor == 0:
            results.append("Jeel")
        else:
            results.append("Ashish")

    # Return results joined by newline
    return '\n'.join(results)

