def dfs_better(chocolates, adj, n):
    best = 0

    for a_start in range(1, n + 1):
        for b_start in range(1, n + 1):
            if a_start == b_start:
                continue

            best = max(best, simulate(chocolates, adj, a_start, b_start))

    return str(best)

def simulate(chocolates, adj, a_start, b_start):
    visited = {a_start, b_start}
    total = chocolates[a_start-1] + chocolates[b_start-1]

    # Alice moves first after initial
    a_pos, b_pos = a_start, b_start

    while True:
        moved = False

        # Try all of Alice's neighbors
        for neighbor in adj[a_pos]:
            if neighbor not in visited:
                visited.add(neighbor)
                total += chocolates[neighbor-1]
                a_pos = neighbor
                moved = True
                break

        if not moved:
            break

        # Bob's turn
        moved = False
        for neighbor in adj[b_pos]:
            if neighbor not in visited:
                visited.add(neighbor)
                total += chocolates[neighbor-1]
                b_pos = neighbor
                moved = True
                break

        if not moved:
            break

    return total

