from decimal import Decimal, getcontext, ROUND_CEILING
getcontext().prec = 50

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    ops = []
    for i in range(1, n + 1):
        t, x_prime, y = map(int, lines[i].split())
        x = Decimal(x_prime) / Decimal(100000)
        ops.append((t, x, y))

    # dp[j] = earliest time step to reach exactly j bananas, or -1 if unreachable
    dp = [-1] * (m + 1)
    dp[0] = 0

    # Current reachable banana counts
    current_reachable = {0}

    for i, (t, x, y) in enumerate(ops, 1):
        next_reachable = set(current_reachable)

        for banana_count in list(current_reachable):
            if t == 1:
                # Addition: k := ⌈k + x⌉
                # Try applying a times, a in [1, y]
                for a in range(1, y + 1):
                    # Sum up: k + ceil(k + x) + ... m times
                    # Handle potential floating point issues with Decimal
                    current_sum = Decimal(banana_count)
                    for _ in range(a):
                        current_sum = current_sum + x
                        current_sum = current_sum.to_integral_value(rounding=ROUND_CEILING)

                    final_k = int(current_sum)
                    if 1 <= final_k <= m and dp[final_k] == -1:
                        next_reachable.add(final_k)
                        dp[final_k] = i
            else:
                # Multiplication: k := ⌈k * x⌉
                # Try applying a times, a in [1, y]
                for a in range(1, y + 1):
                    temp = Decimal(banana_count)
                    for _ in range(a):
                        temp = temp * x
                        temp = temp.to_integral_value(rounding=ROUND_CEILING)

                    final_k = int(temp)
                    if 1 <= final_k <= m and dp[final_k] == -1:
                        next_reachable.add(final_k)
                        dp[final_k] = i

        current_reachable = next_reachable

    # Build result for banana counts 1 to m
    result_values = []
    for j in range(1, m + 1):
        if dp[j] == -1:
            result_values.append("-1")
        else:
            result_values.append(str(dp[j]))

    return " ".join(result_values) + "\n"

