def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    nums = list(map(int, lines[1].split()))

    def check_is_gp(arr):
        """Check if arr is a geometric progression"""
        length = len(arr)
        if length <= 2:
            return True

        # If first element is 0
        if arr[0] == 0:
            # If all elements are 0, it's a GP
            if arr[1] == 0:
                for i in range(2, length):
                    if arr[i] != 0:
                        return False
                return True
            else:
                # If first element is 0 but others aren't, can't form GP
                return False

        # Calculate common ratio from first two elements
        ratio = arr[1] / arr[0]
        for i in range(2, length):
            # Check if current element equals previous * ratio
            if arr[i] != arr[i-1] * ratio:
                return False
        return True

    # Try each position to check if the original sequence is already a GP
    if check_is_gp(nums):
        return "0\n"

    # Try removing each element one by one
    for i in range(len(nums)):
        # Create new sequence without element at index i
        temp = nums[:i] + nums[i+1:]
        if check_is_gp(temp):
            return "1\n"

    return "2\n"

