def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return '0'

    parts = input_str.split()
    if len(parts) < 2:
        return '0'

    n, m = map(int, parts)
    total = n * m

    if total == 0:
        return '0'
    if total == 1:
        return '0'

    # cell_coverage[i] = set of starting cells that can reach destination i
    cell_coverage = []
    for r in range(n):
        for c in range(m):
            reachable = set()
            for rr in range(n):
                for cc in range(m):
                    if abs(rr - r) + abs(cc - c) <= 1:
                        reachable.add(rr * m + cc)
            cell_coverage.append(reachable)

    all_cells = set(range(total))

    def solve_with_k(k):
        if k >= total:
            return True
        remaining = set(all_cells)
        start_idx = 0

        def dfs(paths_left, cells_left, idx):
            if not cells_left:
                return True
            if paths_left == 0:
                return False
            if idx >= len(cell_coverage):
                return False

            first_elem = min(cells_left)

            for i in range(idx, len(cell_coverage)):
                if first_elem in cell_coverage[i]:
                    new_left = cells_left - cell_coverage[i]
                    if dfs(paths_left - 1, new_left, i + 1):
                        return True

            return False

        return dfs(k, remaining, 0)

    for k in range(1, total + 1):
        if solve_with_k(k):
            return str(total - k)

    return '0'

def solution(input_str):
    """
    Solves the problem of making all rooms (maximum connected areas of dots) 
    rectangles by removing the minimum number of walls (converting '*' to '.').
    """
    input_str = input_str.strip()
    if not input_str:
        return ''

    lines = input_str.split('\n')
    if len(lines) < 1:
        return ''

    first_line = lines[0].split()
    if not first_line:
        return ''

    n, m = int(first_line[0]), int(first_line[1])

    grid = []
    for i in range(n):
        if i + 1 < len(lines):
            row = list(lines[i + 1])
            # Pad row if shorter than m, truncate if longer
            if len(row) < m:
                row.extend([' '] * (m - len(row)))
            else:
                row = row[:m]
            grid.append(row)
        else:
            grid.append([' '] * m)

    # If grid has extra rows beyond n, truncate
    grid = grid[:n]

    visited = [[False] * m for _ in range(n)]

    from collections import deque

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                # BFS to find entire connected component of free cells
                component = []
                queue = deque([(r, c)])
                visited[r][c] = True

                while queue:
                    curr_r, curr_c = queue.popleft()
                    component.append((curr_r, curr_c))

                    # Check all 4 directions
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == '.' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Find bounding box of this component
                min_r = min(pos[0] for pos in component)
                max_r = max(pos[0] for pos in component)
                min_c = min(pos[1] for pos in component)
                max_c = max(pos[1] for pos in component)

                # Fill bounding box with '.' to make the component a rectangle
                for row_idx in range(min_r, max_r + 1):
                    for col_idx in range(min_c, max_c + 1):
