import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    target = math.ceil(math.sqrt(n))
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)
    color = [0] * (n + 1)  # 0: white, 1: gray, 2: black

    result = None

    def dfs(u, d, p):
        nonlocal result
        color[u] = 1
        depth[u] = d
        parent[u] = p

        for v in adj[u]:
            if v != p:
                if color[v] == 1:
                    # Back edge found - cycle detected
                    cycle_len = d - depth[v]
                    if cycle_len >= target:
                        path = []
                        curr = u
                        for _ in range(cycle_len):
                            path.append(curr)
                            curr = parent[curr]
                        path.append(v)
                        result = (2, path)
                        return
                elif color[v] == 0:
                    dfs(v, d + 1, u)

        color[u] = 2

    cycle_found = False
    for i in range(1, n + 1):
        if color[i] == 0:
            result_cycle = None
            def dfs_detect(u, d, p):
                nonlocal result_cycle
                if result_cycle is not None:
                    return
                color[u] = 1
                depth[u] = d
                parent[u] = p

                for v in adj[u]:
                    if v != p:
                        if color[v] == 1:
                            cycle_len = d - depth[v]
                            if cycle_len >= target:
                                result_cycle = []
                                curr = u
                                for _ in range(cycle_len):
                                    result_cycle.append(curr)
                                    curr = parent[curr]
                                result_cycle.append(v)
                                return
                        elif color[v] == 0:
                            dfs_detect(v, d + 1, u)

                color[u] = 2

            dfs_detect(i, 1, 0)
            if result_cycle is not None:
                return f"2\n{len(result_cycle)}\n{' '.join(map(str, result_cycle))}"

    # Independent set - nodes at same depth parity in DFS tree
    even_depths = []
    odd_depths = []
    for i in range(1, n + 1):
        if depth[i] % 2 == 0:
            even_depths.append(i)
        else:
            odd_depths.append(i)

    result_set = even_depths if len(even_depths) >= target else odd_depths

    return f"1\n{' '.join(map(str, result_set))}"

from functools import lru_cache

def solution(input_str):
    """
    Solves the game of eating chocolates on a hexagonal grid.
    Karlsson goes first and wins if they can make a move that leads to a losing position for the opponent.
    """
    # Parse input
    lines = [l.strip() for l in input_str.strip().split('\n')]
    board = [c for line in lines for c in line.split()]

    n = 19
    row_start = [0, 3, 7, 12, 16]
    row_len = [3, 4, 5, 4, 3]

    # Build adjacency based on hexagonal structure
    adj = [set() for _ in range(n)]

    for r in range(5):
        for c in range(row_len[r]):
            i = row_start[r] + c

            # Horizontal connections within same row
            if c > 0:
                adj[i].add(i - 1)
            if c < row_len[r] - 1:
                adj[i].add(i + 1)

            # Top-right connections (to row r-1)
            if r > 0:
                prev_len = row_len[r-1]
                if 0 <= c < prev_len:
                    prev_idx = row_start[r-1] + c
                    adj[i].add(prev_idx)
                if 0 <= c - 1 < prev_len:
                    prev_idx = row_start[r-1] + (c - 1)
                    adj[i].add(prev_idx)

            # Bottom-left connections (to row r+1)
            if r < 4:
                next_len = row_len[r+1]
                if 0 <= c < next_len:
                    next_idx = row_start[r+1] + c
                    adj[i].add(next_idx)
                if 0 <= c - 1 < next_len:
                    next_idx = row_start[r+1] + (c - 1)
                    adj[i].add(next_idx)
                if 0 <= c - 2 < next_len:
                    next_idx = row_start[r+1] + (c - 2)
                    adj[i].add(next_idx)

    # Precompute all possible move patterns based on adjacency
    # A move can eat 1+ consecutive O cells along any adjacent path in the hex grid
    def get_all_moves(mask):
        moves = []
        visited = set()

        for start in range(n):
            if not (mask & (1 << start)):
                continue

            # BFS to find all valid connected groups of O cells
            queue = [start]
            group = set()

            while queue:
                curr = queue.pop(0)
                if curr not in visited:
                    if mask & (1 << curr):
                        group.add(curr)
                        visited.add(curr)
                        queue.extend(adj[curr])
                    else:
                        visited.add(curr)

            if len(group) >= 1:
                moves.append frozenset(group)

        return moves

    # DFS with memoization to determine if current player can win
    @lru_cache(maxsize=None)
    def can_win(mask):
        if mask == 0:
            return False

        # Try all possible moves
        for group in get_all_moves(mask):
            weight = 1
            for i in group:
                if mask & (1 << i):
                    pass

            new_mask = mask
            for i in group:
                if mask & (1 << i):
                    new_mask ^= (1 << i)
                else:
                    break

            if not can_win(new_mask):
                return True

        return False

    initial_mask = 0
    for i, cell in enumerate(board):
        if cell == 'O':
            initial_mask |= (1 << i)

    return "Karlsson" if can_win(initial_mask) else "Lilleboren\n"

