def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        if i >= len(lines):
            return "NO"
        parts = list(map(int, lines[i].split()))
        if len(parts) < 1:
            return "NO"
        k = parts[0]
        clause = parts[1:]
        clauses.append(clause)

    # Track which clauses each variable appears in
    var_occurrence = [[] for _ in range(m + 1)]
    for i, clause in enumerate(clauses):
        for lit in clause:
            var_occurrence[abs(lit)].append(i)

    # Assignment: var_value[var] = 1 means True, -1 means False, 0 means unassigned
    var_value = [0] * (m + 1)

    def is_satisfied(clause):
        for lit in clause:
            var = abs(lit)
            val = var_value[var]
            if lit > 0:
                if val == 1:
                    return True
            else:
                if val == -1:
                    return True
        return False

    # Process each clause
    for i, clause in enumerate(clauses):
        if is_satisfied(clause):
            continue

        # Clause not satisfied - find unassigned literals
        unassigned = []
        for lit in clause:
            if var_value[abs(lit)] == 0:
                unassigned.append(lit)

        if not unassigned:
            return "NO"

        # Pick first unassigned literal and assign it
        lit = unassigned[0]
        var = abs(lit)

        if lit > 0:
            var_value[var] = 1
        else:
            var_value[var] = -1

    # Verify all clauses are satisfied
    for clause in clauses:
        if not is_satisfied(clause):
            return "NO"

    # Build assignment string
    result = []
    for i in range(1, m + 1):
        result.append('1' if var_value[i] == 1 else '0')

    return "YES\n" + "".join(result)


