def solution(input_str):
    lines = input_str.strip().split('\n')
    N, M = map(int, lines[0].split())
    A = list(map(int, lines[1].split()))

    if M <= 200000:
        # Direct computation for small M
        A_set = set(A)
        B_set = set(range(M)) - A_set

        reachable = set()
        for a in A:
            for b in B_set:
                reachable.add((a + b) % M)

        unreachable = [r for r in range(M) if r not in reachable]
        k = len(unreachable)
        result = f"{k}\n"
        if k > 0:
            result += " ".join(map(str, unreachable)) + "\n"
        return result
    else:
        # For large M, compute A - A as heuristic
        diffs = set()
