    base_primes = [i for i, is_p in enumerate(sieve) if is_p]

    # Create segment for range [l, r]
    n = r - l + 1
    is_prime = [True] * n

    # Mark 2 as prime (if it's in range) - special case
    if l <= 2 <= r:
        is_prime[2 - l] = True

