        return "NO\n"

    if n == 1:
        return strings[0] + "\n"

    # Build deterministic transition graph - validation
    transitions = {}
    for s in strings:
        for i in range(len(s) - 1):
            if s[i] in transitions:
                if transitions[s[i]] != s[i+1]:
                    return "NO\n"
            transitions[s[i]] = s[i+1]

    # Find start node (in-degree = 0)
    in_deg = defaultdict(int)
    out_deg = defaultdict(int)

    for src, tgt in transitions.items():
        out_deg[src] += 1
        in_deg[tgt] += 1

    start_nodes = [s for s in transitions.keys() if in_deg[s] == 0]

    if len(start_nodes) != 1:
        return "NO\n"

    # Build path
    path = []
    curr = start_nodes[0]

    while True:
        path.append(curr)
        if curr not in transitions:
            break
        curr = transitions[curr]
        if curr in path[:-1]:
            return "NO\n"

    result = "".join(path)

    # Verify all strings are substrings
    for s in strings:
        if s not in result:
            return "NO\n"

    return result + "\n"

def count_visible_pairs(n, heights):
    ans = 0
    for i in range(n):
        max_height = heights[i]
        visible = 0
        for j in range(n):
            if j == i:
                continue
            # Check if i and j can see each other
            # Compute the two paths between i and j
            # Path 1: going clockwise from i, stop before i
            # Path 2: going counter-clockwise from i, stop before i
            for path in [range(i+1, i+n+1)[1:n+1][:-1], range(i-1, i-n-1, -1)[1:n+1][::-1]]:
                if not path:
                    continue
                max_on_path = heights[path[0]]
                can_see = True
                for k in path:
                    if heights[k] > max_height:
                        can_see = False
                        break
                if can_see:
                    visible += 1
                    break
        ans += visible
    return ans // 2

