        [(0, 0), (1, 0), (2, 0), (1, 1)],  # left vertical bar, middle right
        [(0, 0), (1, 0), (1, 1), (1, 2)],  # middle horizontal, top down
        [(0, 0), (0, 1), (1, 1), (2, 1)],  # bottom vertical, middle up
    ]

