        for dr, dc in pattern:
            grid[r + dr][c + dc] = letter

    def clear(r, c, pattern):
        for dr, dc in pattern:
            grid[r + dr][c + dc] = '.'

    def backtrack(count):
        nonlocal best_count, best_solution

        if count > best_count:
            best_count = count
            best_solution = [row[:] for row in grid]

        # Find first empty cell
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    # Try to place each orientation
                    for patt_idx, pattern in enumerate(orientations):
                        if can_place(r, c, pattern):
                            letter = chr(ord('A') + count)
                            place(r, c, pattern, letter)

                            # Recursively place more
                            backtrack(count + 1)

                            clear(r, c, pattern)

                    break  # Only try from first empty cell

    backtrack(0)

    result = str(best_count) + '\n'
